#include <cstdlib>

int main() {
    int n, pos, l, r;
    std::scanf("%d%d%d%d", &n, &pos, &l, &r);

    int ans;
    if (l == 1 && r == n) {
        ans = 0;
    } else if (l == 1) {
        ans = std::abs(pos - r) + 1;
    } else if (r == n) {
        ans = std::abs(pos - l) + 1;
    } else {
        ans = std::min(std::abs(pos - l), std::abs(pos - r))
              + (r - l) + 2;
    }

    std::printf("%d\n", ans);
    return 0;
}

#include <iostream>
#include <cstdio>
#include <algorithm>

int get(int n, int pos, int l, int r)
{
    int left = l - 1;
    int right = n - r;

    if (left == 0 && right == 0)
        return 0;
    if (left == 0)
        return r - pos + 1;
    if (right == 0)
        return pos - l + 1;

    return std::min(pos - l, r - pos) + (r - l) + 2;
}

int main()
{
    int n, pos, l, r;
    std::scanf("%d%d%d%d", &n, &pos, &l, &r);

    int ans;

    if (l == 1 && r == n)
        ans = 0;
    else if (pos < l)
        ans = (l - pos) + get(n, l, l, r);
    else if (pos > r)
        ans = (pos - r) + get(n, r, l, r);
    else
        ans = get(n, pos, l, r);

    std::printf("%d\n", ans);
    return 0;
}

